 search(value){P.query=value;redraw();const el=document.getElementById('cs-policy-search');el?.focus();el?.setSelectionRange?.(value.length,value.length);},
 render(){const rows=P.db.filter(p=>(p.name+' '+p.description).toLowerCase().includes(P.query.toLowerCase()));return `<div class="cs-shared-page">${A.heading('共享策略','防护策略','配置检测能力、规则组合和处置动作，在内容安全防护中绑定应用。',`<button class="btn primary" onclick="App.contentPolicies.edit()">＋ 新建策略</button>`)}<section class="card"><div class="toolbar cs-rule-toolbar"><input id="cs-policy-search" class="input" aria-label="搜索防护策略" placeholder="搜索策略名称" value="${E(P.query)}" oninput="App.contentPolicies.search(this.value)"><span class="muted">${rows.length} 条策略</span></div><div class="table-wrap"><table class="cs-shared-table"><thead><tr><th>策略名称</th><th>检测阶段</th><th>内容类型</th><th>检测能力</th><th>不安全内容处置</th><th>版本 / 状态</th><th>操作</th></tr></thead><tbody>${rows.map(p=>{const pub=P.latest(p.id),active=pub||p;return `<tr><td><strong>${E(p.name)}</strong><small>${E(p.description)}</small></td><td>${stageNames[active.stage]}</td><td>${typeNames[active.contentType]}</td><td>${P.detectorNames(active).map(E).join('、')}<small>${active.ruleIds?.length||0} 条规则 · ${active.ruleOperator||'OR'}</small></td><td>${active.unsafeAction==='allow'?A.badge('放行不安全内容','red'):E(actions[active.unsafeAction]||'阻断')}</td><td>${pub?`V${pub.version}`:'未发布'} ${A.badge(pub?.enabled?'开启':'停用',pub?.enabled?'green':'gray')}${p.hasDraft?'<small>有待发布草稿</small>':''}</td><td class="cs-table-actions"><button class="link-btn" onclick="App.contentPolicies.detail('${p.id}')">详情</button><button class="link-btn" onclick="App.contentPolicies.edit('${p.id}')">编辑</button></td></tr>`;}).join('')||'<tr><td colspan="7" class="empty">没有匹配的策略</td></tr>'}</tbody></table></div></section></div>`;},
