 edit(id){const p=P.get(id);P.draft=p?copy(p):{name:'',description:'',stage:'both',contentType:'text',enabled:false,detectors:{compliance:true,sensitive:false,promptAttack:false,image:false},ruleIds:[],ruleOperator:'OR',controversialAction:'review',unsafeAction:'block',revisions:[]};P.form();},
