D.embeddingField=function(d){const models=P.modelCandidates('embedding');return `<div class="field dp-semantic-model"><label for="dp-embedding">语义检测模型</label><select id="dp-embedding" onchange="App.defensePolicies.draft.embeddingModelId=this.value"><option value="">请选择 Embedding 模型</option>${models.map(m=>`<option value="${E(m.id)}" ${d.embeddingModelId===m.id?'selected':''}>${E(m.name||m.model)}</option>`).join('')}</select><p class="field-help">语义规则使用此模型计算相似度；请在平台管理 → 模型配置中为模型启用语义检索用途。</p></div>`;};
