 if(!A.data.defenseServices){const m=P.modelRecord('system-qwen3guard');A.data.defenseServices={text:{id:'system-qwen3guard',name:'Qwen3Guard',model:m?.model||'Qwen/Qwen3Guard-Gen-4B',endpoint:m?.endpoint||'http://guard-inference:8000/v1',status:'ready',version:1,protocol:'qwen3guard',labels:['Safe','Controversial','Unsafe']},image:{id:'dedicated-singguard',name:'SingGuard-4B',model:'inclusionAI/SingGuard-4b',endpoint:'http://image-guard:8000/v1',status:'ready',version:1,protocol:'singguard',labels:['safe','unsafe']}};}
 if(!Array.isArray(A.data.guardReplyTemplates))A.data.guardReplyTemplates=[{id:'reply-general',name:'通用安全提示',text:'暂时无法处理该请求，请调整内容后重试。',enabled:true},{id:'reply-pii',name:'个人信息保护',text:'内容涉及个人信息，请移除敏感信息后重试。',enabled:true},{id:'reply-context',name:'补充业务语境',text:'当前内容需要进一步确认，请补充用途或调整表述后重试。',enabled:true}];
 if(A.data.sharedDefenseVersion)return;
 const legacy=P.db.filter(p=>p.appId&&p.policyType&&!p.archived),mapped=new Map();
 for(const type of ['compliance','pii','prompt','image']){
  const source=legacy.find(p=>p.policyType===type&&p.enabled)||legacy.find(p=>p.policyType===type);
  const d={...D.newDraft(type),...(source?copy(source):{}),id:'defense-standard-'+type,name:D.names[type],isStandard:true,stage:type==='prompt'?'input':'both',enabled:source?source.enabled:type!=='image',revisions:[]};delete d.appId;delete d.archived;D.store(d,false);
 }
 for(const old of legacy){let target=D.policyRows().find(p=>D.specKey(p)===D.specKey(old));if(!target){const d={...copy(old),id:uid('defense'),isStandard:false,name:old.name+' · '+S.appName(old.appId)+'配置',revisions:[]};delete d.appId;delete d.archived;target=D.store(d,false);}mapped.set(old.id,target.id);old.archived=true;}
 for(const app of S.apps){let b=S.binding(app.id);if(!b){b={id:uid('binding'),appId:app.id};S.db.bindings.push(b);}if(Array.isArray(b.policyLinks))continue;const previous=legacy.filter(p=>p.appId===app.id);b.policyLinks=previous.length?previous.filter(p=>p.enabled).map(p=>({policyId:mapped.get(p.id),version:P.latest(mapped.get(p.id)).version,stage:p.stage})):['compliance','pii','prompt'].map(type=>{const p=D.standard(type);return {policyId:p.id,version:P.latest(p.id).version,stage:type==='prompt'?'input':'both'};});}
