D.detail=function(id,version){const p=version?CP.get(id,version):CP.latest(id);if(!p)return;const k=D.kinds[p.policyType];A.drawer(E(p.name),`<div class="gr-config"><div class="cs-detail-summary">${A.badge(stages[p.stage],'blue')}</div><p>${E(k.description)}</p><section><h3>检测类别 · ${arr(p.modelCategories).length} 类</h3><p>${p.policyType==='custom'?arr(p.customRules).map(r=>E(r.name||'规则组合')).join('、'):arr(p.modelCategories).map(id=>E(k.categories.find(c=>c[0]===id)?.[1]||id)).join('、')||'未选择检测类别'}</p></section><section><h3>可修改参数</h3><p>${p.policyType==='custom'?'此为历史规则组合，可继续被策略配置引用；新增组合统一在策略配置中维护。':`检测类别可在“修改参数”中编辑。模型审核模板和输出结构固定维护；生效位置和处置由策略配置决定。`}</p></section></div>`,`<button class="btn" onclick="App.closeDrawer()">关闭</button>`);};
